#!/usr/bin/env python3
"""Generate src/htspsl_data.c from the Public Suffix List.

Usage: psl-gen.py [--check] [LIST] [OUTPUT]

LIST defaults to the upstream URL and OUTPUT to src/htspsl_data.c. With
--check, compare the rules against OUTPUT and exit 1 when they differ.
"""

import re
import sys
import urllib.request
from pathlib import Path

URL = "https://publicsuffix.org/list/public_suffix_list.dat"
OUTPUT = Path(__file__).resolve().parent.parent / "src" / "htspsl_data.c"

HEADER = """\
/* Generated by tools/psl-gen.py from {url}.
   Do not edit: run "python3 tools/psl-gen.py" to refresh it.

   The rules are the Public Suffix List, subject to the terms of the Mozilla
   Public License, v. 2.0. If a copy of the MPL was not distributed with this
   file, you can obtain one at https://mozilla.org/MPL/2.0/. */

#define HTS_INTERNAL_BYTECODE

#include "htspsl.h"

const char hts_psl_builtin_version[] = "{version}";

const char *const hts_psl_builtin[] = {{
"""


def read_list(source):
    if re.match(r"^https?://", source):
        with urllib.request.urlopen(source, timeout=60) as reply:
            return reply.read().decode("utf-8")
    return Path(source).read_text(encoding="utf-8")


def parse(text):
    """Return (version, rules), each rule as the list spells it."""
    version = ""
    rules = []
    for line in text.splitlines():
        line = line.strip()
        match = re.match(r"^// VERSION: (\S+)", line)
        if match:
            version = match.group(1)
        if not line or line.startswith("//"):
            continue
        rules.append(line.split()[0])
    if not version or len(rules) < 1000:
        sys.exit("psl-gen: this does not look like the Public Suffix List")
    return version, rules


def c_string(rule):
    """Spell a rule as a C literal, with octal escapes for non-ASCII bytes."""
    out = []
    for byte in rule.encode("utf-8"):
        if byte < 0x80 and chr(byte) not in '"\\':
            out.append(chr(byte))
        else:
            out.append("\\%03o" % byte)
    return '"' + "".join(out) + '"'


def render(version, rules):
    body = "".join("    %s,\n" % c_string(rule) for rule in rules)
    return HEADER.format(url=URL, version=version) + body + "    NULL,\n};\n"


def rules_in(c_source):
    return re.findall(r'^    (".*"),$', c_source, flags=re.M)


def main(argv):
    check = "--check" in argv
    args = [a for a in argv if a != "--check"]
    source = args[0] if args else URL
    output = Path(args[1]) if len(args) > 1 else OUTPUT
    version, rules = parse(read_list(source))
    text = render(version, rules)
    if check:
        old = output.read_text(encoding="ascii")
        if rules_in(old) != rules_in(text):
            print("psl-gen: %s is older than the list at %s" % (output, version))
            return 1
        print("psl-gen: %s matches the list at %s" % (output, version))
        return 0
    output.write_text(text, encoding="ascii")
    print("psl-gen: wrote %d rules at %s to %s" % (len(rules), version, output))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
